    # a crash in a later split does not lose the earlier one's trajectories.
    os.makedirs(run_dir, exist_ok=True)
    # Eval can run weeks after training, on a stack that moved in between, so it
    # records its own half of runs/<exp>/env_stamp.json rather than sharing the
    # training one.
    write_env_stamp(
        run_dir,
        "eval",
        (config.get("training", {}).get("env_server", {}) or {}).get(
            "repo_path", DEFAULT_REPO_ENVS_PATH
        ),
    )
    split_metrics = {}
    for split in splits:
        n = split["n_episodes"]
        if config.get("_smoke"):
            # A multi-turn agentic eval runs n * up-to-max_turns model.generate
            # calls, so keep the smoke episode count small - it only checks that
            # the eval loop runs.
            n = min(n, 4)
