        if self._capture_loss_logps:
            self._current_loss_logps = result[0]
        return result

    def _compute_loss(self, model, inputs):
        self._capture_loss_logps = True
        self._current_loss_logps = None
        try:
            loss = super()._compute_loss(model, inputs)
